/**
 * express-auto-swagger
 * Automatically generate OpenAPI 3.0 specifications and serve Swagger UI for Express.js applications
 */

/**
 * Helper function to normalize and combine paths
 */
function normalizePath(basePath, routePath) {
    // Handle empty or root paths
    if (!basePath || basePath === '/') basePath = '';
    if (!routePath || routePath === '/') routePath = '/';
    
    // Remove trailing slashes except for root
    basePath = basePath.replace(/\/$/, '');
    if (routePath !== '/') {
        routePath = routePath.replace(/\/$/, '');
    }
    
    // Combine paths
    const combined = basePath + routePath;
    
    // Ensure path starts with /
    return combined.startsWith('/') ? combined : '/' + combined;
}

/**
 * Route registry to store discovered routes with grouping support
 */
class RouteRegistry {
    constructor() {
        this.routes = [];
        this.routeGroups = {}; // Store routes grouped by router/tag
        this.models = {}; // Store model schemas
    }

    addRoute(method, path, options = {}) {
        try {
            // Validate inputs
            if (!method || typeof method !== 'string') {
                throw new Error('Method must be a non-empty string');
            }

            if (!path) {
                throw new Error('Path cannot be empty or null');
            }

            // Convert path to string if it's not already
            const pathStr = typeof path === 'string' ? path : String(path);

            // Avoid duplicate routes
            const existingRoute = this.routes.find(
                route => route.method === method.toUpperCase() && route.path === pathStr
            );

            if (!existingRoute) {
                const route = {
                    method: method.toUpperCase(),
                    path: pathStr,
                    originalPath: pathStr,
                    group: options.group || 'default',
                    routerPath: options.routerPath || null,
                    model: options.model || null,
                    tags: options.tags || []
                };
                
                this.routes.push(route);
                
                // Group routes by their group/tag
                if (!this.routeGroups[route.group]) {
                    this.routeGroups[route.group] = [];
                }
                this.routeGroups[route.group].push(route);
            }
        } catch (error) {
            console.warn(`express-auto-swagger: Failed to add route to registry:`, error.message);
        }
    }

    addModel(name, schema) {
        try {
            if (!name || typeof name !== 'string') {
                throw new Error('Model name must be a non-empty string');
            }
            this.models[name] = schema;
        } catch (error) {
            console.warn(`express-auto-swagger: Failed to add model:`, error.message);
        }
    }

    getModel(name) {
        return this.models[name] || null;
    }

    getRoutes() {
        return [...this.routes]; // Return a copy to prevent external modification
    }

    getRouteGroups() {
        return { ...this.routeGroups };
    }

    clear() {
        this.routes = [];
        this.routeGroups = {};
    }

    // Additional utility methods for error handling
    hasRoute(method, path) {
        return this.routes.some(
            route => route.method === method.toUpperCase() && route.path === path
        );
    }

    getRouteCount() {
        return this.routes.length;
    }
}

/**
 * Route interceptor that wraps Express HTTP methods for both app and routers
 */
function createRouteInterceptor(app, registry, config) {
    const httpMethods = ['get', 'post', 'put', 'delete', 'patch'];
    const originalMethods = {};
    const originalRouterMethods = {};

    // Store original app methods
    httpMethods.forEach(method => {
        if (typeof app[method] === 'function') {
            originalMethods[method] = app[method].bind(app);
        }
    });

    // Store original Router constructor and methods
    const express = require('express');
    const originalRouter = express.Router;
    
    // Wrap Router constructor to intercept router creation
    express.Router = function(options) {
        const router = originalRouter.call(this, options);
        
        // Initialize route tracking with metadata
        router._autoSwaggerRoutes = [];
        router._autoSwaggerGroup = null;
        router._autoSwaggerModel = null;
        
        // Intercept router methods
        httpMethods.forEach(method => {
            if (typeof router[method] === 'function') {
                const originalRouterMethod = router[method].bind(router);
                
                router[method] = function(path, ...handlers) {
                    try {
                        // Register router routes with base path tracking
                        if (typeof path === 'string' && path.trim()) {
                            const shouldSkip = 
                                path.includes('query parser') ||
                                path.includes('json escape') ||
                                path.includes('json replacer') ||
                                path.includes('json spaces') ||
                                path.includes('etag fn') ||
                                path.includes('env') ||
                                path.includes('trust proxy') ||
                                path.includes('subdomain offset') ||
                                path.includes('x-powered-by') ||
                                path.includes('case sensitive routing') ||
                                path.includes('strict routing') ||
                                path.includes('view cache') ||
                                path.includes('view engine') ||
                                path.includes('views') ||
                                typeof path !== 'string' ||
                                path.startsWith('*') ||
                                path.endsWith(' fn');
                                
                            if (!shouldSkip) {
                                // Store route info for later processing when router is mounted
                                router._autoSwaggerRoutes.push({
                                    method: method,
                                    path: path,
                                    timestamp: Date.now(),
                                    model: router._autoSwaggerModel
                                });
                            }
                        }
                    } catch (error) {
                        console.warn(`express-auto-swagger: Failed to register router route ${method.toUpperCase()} ${path}:`, error.message);
                    }

                    return originalRouterMethod(path, ...handlers);
                };
            }
        });

        // Also intercept router.use for nested routers
        const originalRouterUse = router.use.bind(router);
        router.use = function(path, ...middlewares) {
            try {
                middlewares.forEach(middleware => {
                    if (middleware && middleware._autoSwaggerRoutes) {
                        const basePath = typeof path === 'string' ? path : '';
                        
                        // Merge nested router routes
                        middleware._autoSwaggerRoutes.forEach(route => {
                            const fullPath = normalizePath(basePath, route.path);
                            router._autoSwaggerRoutes.push({
                                method: route.method,
                                path: fullPath,
                                timestamp: Date.now(),
                                model: route.model || middleware._autoSwaggerModel
                            });
                        });
                    }
                });
            } catch (error) {
                console.warn('express-auto-swagger: Failed to process nested router:', error.message);
            }

            return originalRouterUse(path, ...middlewares);
        };

        return router;
    };

    // Store original app.use method to intercept router mounting
    const originalUse = app.use.bind(app);
    app.use = function(path, ...middlewares) {
        try {
            // Check if any middleware is a router with our tracked routes
            middlewares.forEach(middleware => {
                if (middleware && middleware._autoSwaggerRoutes) {
                    const basePath = typeof path === 'string' ? path : '';
                    const groupName = middleware._autoSwaggerGroup || extractGroupFromPath(basePath);
                    
                    // Register all routes from this router with the base path
                    middleware._autoSwaggerRoutes.forEach(route => {
                        const fullPath = normalizePath(basePath, route.path);
                        registry.addRoute(route.method, fullPath, {
                            group: groupName,
                            routerPath: basePath,
                            model: route.model,
                            tags: [groupName]
                        });
                    });
                }
            });
        } catch (error) {
            console.warn('express-auto-swagger: Failed to process router mounting:', error.message);
        }

        return originalUse(path, ...middlewares);
    };

    // Wrap each HTTP method on the main app
    httpMethods.forEach(method => {
        if (originalMethods[method]) {
            app[method] = function (path, ...handlers) {
                try {
                    // Validate path parameter and filter out internal routes
                    if (typeof path === 'string' && path.trim()) {
                        // Skip internal Express routes and our own documentation routes
                        const shouldSkip = 
                            path.includes('query parser') ||
                            path.includes('json escape') ||
                            path.includes('json replacer') ||
                            path.includes('json spaces') ||
                            path.includes('etag fn') ||
                            path.includes('env') ||
                            path.includes('trust proxy') ||
                            path.includes('subdomain offset') ||
                            path.includes('x-powered-by') ||
                            path.includes('case sensitive routing') ||
                            path.includes('strict routing') ||
                            path.includes('view cache') ||
                            path.includes('view engine') ||
                            path.includes('views') ||
                            path === config.docsPath ||
                            path === config.jsonPath ||
                            typeof path !== 'string' ||
                            path.startsWith('*') ||
                            path.endsWith(' fn');
                            
                        if (!shouldSkip) {
                            // Register the route in our registry (direct app routes)
                            registry.addRoute(method, path, {
                                group: 'Direct Routes',
                                routerPath: null,
                                tags: ['Direct Routes']
                            });
                        }
                    } else if (path instanceof RegExp) {
                        // Handle regex paths - convert to string representation
                        registry.addRoute(method, path.toString(), {
                            group: 'Direct Routes',
                            routerPath: null,
                            tags: ['Direct Routes']
                        });
                    }
                    // Skip registration for invalid paths (arrays, functions, etc.)
                } catch (error) {
                    // Log warning but don't break the application
                    console.warn(`express-auto-swagger: Failed to register route ${method.toUpperCase()} ${path}:`, error.message);
                }

                // Always call the original Express method, but handle errors
                try {
                    return originalMethods[method](path, ...handlers);
                } catch (expressError) {
                    // If Express can't handle the path, we shouldn't either
                    throw expressError;
                }
            };
        }
    });

    return { originalMethods, originalRouterMethods };
}

/**
 * Extract group name from router path
 */
function extractGroupFromPath(path) {
    if (!path || path === '/') return 'default';
    
    // Remove leading/trailing slashes and get first segment
    const segments = path.replace(/^\/|\/$/g, '').split('/');
    const firstSegment = segments[0] || 'default';
    
    // Capitalize first letter
    return firstSegment.charAt(0).toUpperCase() + firstSegment.slice(1);
}

/**
 * Configuration manager with default values
 */
function createConfig(options = {}) {
    try {
        // Handle null/undefined options
        const opts = options || {};
        
        // Validate option types
        if (opts.title && typeof opts.title !== 'string') {
            console.warn('express-auto-swagger: title must be a string, using default');
            opts.title = undefined;
        }
        
        if (opts.version && typeof opts.version !== 'string') {
            console.warn('express-auto-swagger: version must be a string, using default');
            opts.version = undefined;
        }
        
        if (opts.docsPath && typeof opts.docsPath !== 'string') {
            console.warn('express-auto-swagger: docsPath must be a string, using default');
            opts.docsPath = undefined;
        }
        
        if (opts.jsonPath !== undefined && opts.jsonPath !== null && typeof opts.jsonPath !== 'string') {
            console.warn('express-auto-swagger: jsonPath must be a string, using default');
            opts.jsonPath = undefined;
        }

        // Validate paths start with '/'
        const docsPath = opts.docsPath || '/docs';
        const jsonPath = opts.jsonPath || '/openapi.json';
        
        const config = {
            title: opts.title || 'API Documentation',
            version: opts.version || '1.0.0',
            docsPath: docsPath.startsWith('/') ? docsPath : '/' + docsPath,
            jsonPath: jsonPath.startsWith('/') ? jsonPath : '/' + jsonPath,
            security: opts.security || null,
            servers: opts.servers || []
        };

        // Validate paths don't conflict
        if (config.docsPath === config.jsonPath) {
            console.warn('express-auto-swagger: docsPath and jsonPath cannot be the same, adjusting jsonPath');
            config.jsonPath = config.jsonPath + '.json';
        }

        return config;
    } catch (error) {
        console.error('express-auto-swagger: Error creating configuration:', error.message);
        
        // Return safe defaults
        return {
            title: 'API Documentation',
            version: '1.0.0',
            docsPath: '/docs',
            jsonPath: '/openapi.json',
            security: null,
            servers: []
        };
    }
}

/**
 * Transform routes into OpenAPI paths object with model support
 */
function transformRoutesToPaths(routes, registry) {
    const paths = {};

    if (!Array.isArray(routes)) {
        console.warn('express-auto-swagger: Routes must be an array');
        return paths;
    }

    routes.forEach((route, index) => {
        try {
            if (!route || typeof route !== 'object') {
                console.warn(`express-auto-swagger: Invalid route at index ${index}:`, route);
                return;
            }

            const { method, path, tags, model } = route;

            if (!method || !path) {
                console.warn(`express-auto-swagger: Route missing method or path at index ${index}:`, route);
                return;
            }

            const lowerMethod = method.toLowerCase();

            // Validate HTTP method
            const validMethods = ['get', 'post', 'put', 'delete', 'patch', 'head', 'options'];
            if (!validMethods.includes(lowerMethod)) {
                console.warn(`express-auto-swagger: Invalid HTTP method "${method}" for path "${path}"`);
                return;
            }

            // Initialize path object if it doesn't exist
            if (!paths[path]) {
                paths[path] = {};
            }

            // Create operation object
            const operation = {
                summary: `${method} ${path}`,
                tags: tags || [],
                responses: {
                    '200': {
                        description: 'Success'
                    },
                    '400': {
                        description: 'Bad Request'
                    },
                    '500': {
                        description: 'Internal Server Error'
                    }
                }
            };

            // Get model schema if available
            let modelSchema = null;
            if (model && registry) {
                modelSchema = registry.getModel(model);
            }

            // Add request body for methods that typically have one
            if (['post', 'put', 'patch'].includes(lowerMethod)) {
                if (modelSchema) {
                    // Use model schema if available
                    operation.requestBody = {
                        description: `${model || 'Request'} body`,
                        required: true,
                        content: {
                            'application/json': {
                                schema: modelSchema
                            }
                        }
                    };
                } else {
                    // Fallback to auto-generated schema
                    operation.requestBody = {
                        description: 'Request body',
                        required: true,
                        content: {
                            'application/json': {
                                schema: {
                                    type: 'object',
                                    properties: generateSchemaFromPath(path, lowerMethod),
                                    example: generateExampleFromPath(path, lowerMethod)
                                }
                            }
                        }
                    };
                }
            }

            // Add response schema for GET requests
            if (lowerMethod === 'get' && modelSchema) {
                operation.responses['200'] = {
                    description: 'Success',
                    content: {
                        'application/json': {
                            schema: path.includes(':') ? modelSchema : {
                                type: 'array',
                                items: modelSchema
                            }
                        }
                    }
                };
            }

            // Add parameters for parameterized routes
            try {
                const paramMatches = path.match(/:(\w+)/g);
                if (paramMatches) {
                    const parameters = paramMatches.map(param => ({
                        name: param.substring(1), // Remove the ':'
                        in: 'path',
                        required: true,
                        schema: {
                            type: 'string'
                        },
                        description: `${param.substring(1)} parameter`
                    }));
                    operation.parameters = parameters;
                }
            } catch (paramError) {
                console.warn(`express-auto-swagger: Failed to parse parameters for path "${path}":`, paramError.message);
            }

            // Add query parameters for GET requests
            if (lowerMethod === 'get' && (path.includes('search') || path.includes('list') || !path.includes(':'))) {
                if (!operation.parameters) operation.parameters = [];
                
                // Add common query parameters
                operation.parameters.push(
                    {
                        name: 'limit',
                        in: 'query',
                        required: false,
                        schema: { type: 'integer', minimum: 1, maximum: 100, default: 10 },
                        description: 'Number of items to return'
                    },
                    {
                        name: 'offset',
                        in: 'query',
                        required: false,
                        schema: { type: 'integer', minimum: 0, default: 0 },
                        description: 'Number of items to skip'
                    }
                );
            }

            paths[path][lowerMethod] = operation;
        } catch (error) {
            console.warn(`express-auto-swagger: Failed to process route at index ${index}:`, error.message);
        }
    });

    return paths;
}

/**
 * Generate schema properties based on path and method
 */
function generateSchemaFromPath(path, method) {
    const properties = {};

    // Generate schema based on path patterns
    if (path.includes('/users')) {
        if (method === 'post') {
            properties.name = { type: 'string', description: 'User name' };
            properties.email = { type: 'string', format: 'email', description: 'User email address' };
            properties.age = { type: 'integer', minimum: 0, description: 'User age' };
        } else if (method === 'put' || method === 'patch') {
            properties.name = { type: 'string', description: 'User name' };
            properties.email = { type: 'string', format: 'email', description: 'User email address' };
            properties.age = { type: 'integer', minimum: 0, description: 'User age' };
        }
    } else if (path.includes('/posts')) {
        if (method === 'post') {
            properties.title = { type: 'string', description: 'Post title' };
            properties.content = { type: 'string', description: 'Post content' };
            properties.userId = { type: 'integer', description: 'ID of the user who created the post' };
        } else if (method === 'put' || method === 'patch') {
            properties.title = { type: 'string', description: 'Post title' };
            properties.content = { type: 'string', description: 'Post content' };
        }
    } else if (path.includes('/products')) {
        if (method === 'post') {
            properties.name = { type: 'string', description: 'Product name' };
            properties.price = { type: 'number', format: 'float', description: 'Product price' };
            properties.category = { type: 'string', description: 'Product category' };
        } else if (method === 'put' || method === 'patch') {
            properties.name = { type: 'string', description: 'Product name' };
            properties.price = { type: 'number', format: 'float', description: 'Product price' };
        }
    } else if (path.includes('/auth/login')) {
        properties.username = { type: 'string', description: 'Username or email' };
        properties.password = { type: 'string', format: 'password', description: 'User password' };
    } else if (path.includes('/auth/register')) {
        properties.name = { type: 'string', description: 'User full name' };
        properties.email = { type: 'string', format: 'email', description: 'User email address' };
        properties.password = { type: 'string', format: 'password', description: 'User password' };
        properties.age = { type: 'integer', minimum: 0, description: 'User age (optional)' };
    } else {
        // Generic properties for unknown endpoints
        properties.data = { type: 'object', description: 'Request data' };
    }

    return properties;
}

/**
 * Generate example request body based on path and method
 */
function generateExampleFromPath(path, method) {
    if (path.includes('/users')) {
        if (method === 'post') {
            return {
                name: 'John Doe',
                email: 'john.doe@example.com',
                age: 30
            };
        } else if (method === 'put' || method === 'patch') {
            return {
                name: 'John Smith',
                email: 'john.smith@example.com',
                age: 31
            };
        }
    } else if (path.includes('/posts')) {
        if (method === 'post') {
            return {
                title: 'My New Post',
                content: 'This is the content of my new post.',
                userId: 1
            };
        } else if (method === 'put' || method === 'patch') {
            return {
                title: 'Updated Post Title',
                content: 'This is the updated content.'
            };
        }
    } else if (path.includes('/auth/login')) {
        return {
            username: 'user@example.com',
            password: 'password123'
        };
    }

    return { data: 'example value' };
}

/**
 * Generate OpenAPI 3.0 specification from routes and config with model support
 */
function generateOpenAPISpec(routes, config, registry) {
    try {
        // Validate inputs
        if (!config || typeof config !== 'object') {
            throw new Error('Configuration object is required');
        }

        if (!routes) {
            console.warn('express-auto-swagger: No routes provided, generating empty spec');
            routes = [];
        }

        const spec = {
            openapi: '3.0.0',
            info: {
                title: config.title || 'API Documentation',
                version: config.version || '1.0.0',
                description: 'API documentation generated automatically by express-auto-swagger'
            },
            paths: transformRoutesToPaths(routes, registry),
            tags: generateTags(routes),
            components: {
                schemas: registry ? registry.models : {},
                securitySchemes: {}
            }
        };

        // Add servers if configured
        if (config.servers && config.servers.length > 0) {
            spec.servers = config.servers;
        }

        // Add security schemes if configured
        if (config.security) {
            if (config.security.jwt || config.security.bearer) {
                spec.components.securitySchemes.BearerAuth = {
                    type: 'http',
                    scheme: 'bearer',
                    bearerFormat: 'JWT',
                    description: 'Enter your JWT token'
                };
                spec.security = [{ BearerAuth: [] }];
            }
            
            if (config.security.apiKey) {
                spec.components.securitySchemes.ApiKeyAuth = {
                    type: 'apiKey',
                    in: config.security.apiKey.in || 'header',
                    name: config.security.apiKey.name || 'X-API-Key',
                    description: 'API Key for authentication'
                };
                if (!spec.security) spec.security = [];
                spec.security.push({ ApiKeyAuth: [] });
            }

            if (config.security.basic) {
                spec.components.securitySchemes.BasicAuth = {
                    type: 'http',
                    scheme: 'basic',
                    description: 'Basic HTTP authentication'
                };
                if (!spec.security) spec.security = [];
                spec.security.push({ BasicAuth: [] });
            }

            if (config.security.oauth2) {
                spec.components.securitySchemes.OAuth2 = {
                    type: 'oauth2',
                    flows: config.security.oauth2.flows || {
                        authorizationCode: {
                            authorizationUrl: 'https://example.com/oauth/authorize',
                            tokenUrl: 'https://example.com/oauth/token',
                            scopes: {
                                read: 'Read access',
                                write: 'Write access'
                            }
                        }
                    }
                };
                if (!spec.security) spec.security = [];
                spec.security.push({ OAuth2: [] });
            }
        }

        // Validate the generated spec has required fields
        if (!config.title || !config.version) {
            console.warn('express-auto-swagger: Generated spec missing required info fields');
        }

        return spec;
    } catch (error) {
        console.error('express-auto-swagger: Failed to generate OpenAPI specification:', error.message);
        
        // Return a minimal valid spec as fallback
        return {
            openapi: '3.0.0',
            info: {
                title: 'API Documentation',
                version: '1.0.0',
                description: 'Error occurred while generating API documentation'
            },
            paths: {}
        };
    }
}

/**
 * Generate tags from routes for grouping
 */
function generateTags(routes) {
    const tagSet = new Set();
    
    routes.forEach(route => {
        if (route.tags && Array.isArray(route.tags)) {
            route.tags.forEach(tag => tagSet.add(tag));
        }
    });
    
    return Array.from(tagSet).map(tag => ({
        name: tag,
        description: `${tag} endpoints`
    }));
}

/**
 * Create JSON endpoint that serves OpenAPI specification
 */
function createJsonEndpoint(app, registry, config) {
    app.get(config.jsonPath, (_req, res) => {
        try {
            const routes = registry.getRoutes();
            const spec = generateOpenAPISpec(routes, config, registry);
            res.json(spec);
        } catch (error) {
            res.status(500).json({
                error: 'Failed to generate OpenAPI specification',
                message: error.message
            });
        }
    });
}

/**
 * Create Swagger UI endpoint
 */
function createSwaggerUIEndpoint(app, config) {
    try {
        const swaggerUi = require('swagger-ui-express');

        // Setup Swagger UI with proper middleware handling
        app.use(config.docsPath, swaggerUi.serve);
        app.get(config.docsPath, swaggerUi.setup(null, {
            swaggerOptions: {
                url: config.jsonPath
            },
            customSiteTitle: config.title,
            customCss: '.swagger-ui .topbar { display: none }'
        }));

        return true; // Indicate success
    } catch (error) {
        console.warn('swagger-ui-express not found. Swagger UI endpoint will not be available.');

        // Provide a fallback endpoint with basic information
        app.get(config.docsPath, (req, res) => {
            res.status(503).json({
                error: 'Swagger UI not available',
                message: 'swagger-ui-express dependency is required for the documentation interface',
                jsonEndpoint: config.jsonPath,
                suggestion: 'Install swagger-ui-express: npm install swagger-ui-express'
            });
        });

        return false; // Indicate failure
    }
}

/**
 * Load models from a directory
 */
function loadModels(modelsPath, registry) {
    try {
        const fs = require('fs');
        const path = require('path');
        
        if (!fs.existsSync(modelsPath)) {
            console.warn(`express-auto-swagger: Models directory not found: ${modelsPath}`);
            return;
        }

        const files = fs.readdirSync(modelsPath);
        
        files.forEach(file => {
            if (file.endsWith('.js') || file.endsWith('.json')) {
                try {
                    const modelPath = path.join(modelsPath, file);
                    const modelName = path.basename(file, path.extname(file));
                    
                    // Load the model
                    const modelModule = require(modelPath);
                    
                    // Support different export formats
                    let schema = null;
                    if (modelModule.schema) {
                        schema = modelModule.schema;
                    } else if (modelModule.default && modelModule.default.schema) {
                        schema = modelModule.default.schema;
                    } else if (typeof modelModule === 'object' && modelModule.type) {
                        schema = modelModule;
                    }
                    
                    if (schema) {
                        registry.addModel(modelName, schema);
                        console.log(`express-auto-swagger: Loaded model "${modelName}"`);
                    }
                } catch (error) {
                    console.warn(`express-auto-swagger: Failed to load model ${file}:`, error.message);
                }
            }
        });
    } catch (error) {
        console.warn('express-auto-swagger: Failed to load models:', error.message);
    }
}

/**
 * Main autoSwagger function that orchestrates all components
 * @param {Object} app - Express application instance
 * @param {Object} options - Configuration options
 * @param {string} options.title - API title (default: "API Documentation")
 * @param {string} options.version - API version (default: "1.0.0")
 * @param {string} options.docsPath - Swagger UI path (default: "/docs")
 * @param {string} options.jsonPath - OpenAPI JSON path (default: "/openapi.json")
 * @param {string} options.modelsPath - Path to models directory (optional)
 * @param {Object} options.security - Security configuration (optional)
 * @param {boolean} options.security.jwt - Enable JWT Bearer authentication
 * @param {boolean} options.security.bearer - Enable Bearer token authentication
 * @param {Object} options.security.apiKey - API Key configuration
 * @param {boolean} options.security.basic - Enable Basic authentication
 * @param {Object} options.security.oauth2 - OAuth2 configuration
 * @param {Array} options.servers - Server URLs for the API
 * @returns {Object} - Registry and configuration for advanced usage
 */
function autoSwagger(app, options = {}) {
    // Validate input parameters
    if (!app || typeof app.get !== 'function') {
        throw new Error('autoSwagger requires a valid Express application instance');
    }

    if (options && typeof options !== 'object') {
        throw new Error('autoSwagger options must be an object');
    }

    // Create configuration with defaults
    const config = createConfig(options);

    // Create route registry
    const registry = new RouteRegistry();

    // Load models if modelsPath is provided
    if (options.modelsPath) {
        loadModels(options.modelsPath, registry);
    }

    // Create documentation endpoints BEFORE setting up route interception
    // This prevents the internal documentation routes from being captured
    createJsonEndpoint(app, registry, config);
    createSwaggerUIEndpoint(app, config);

    // Set up route interception AFTER documentation endpoints are created
    createRouteInterceptor(app, registry, config);

    // Helper to bind model to router
    const bindModel = (router, modelName) => {
        if (router && router._autoSwaggerModel === undefined) {
            router._autoSwaggerModel = modelName;
        }
        return router;
    };

    // Helper to set router group name
    const setGroup = (router, groupName) => {
        if (router && router._autoSwaggerGroup === undefined) {
            router._autoSwaggerGroup = groupName;
        }
        return router;
    };

    // Return registry and config for advanced usage
    return {
        registry,
        config,
        getRoutes: () => registry.getRoutes(),
        getRouteGroups: () => registry.getRouteGroups(),
        getSpec: () => generateOpenAPISpec(registry.getRoutes(), config, registry),
        addModel: (name, schema) => registry.addModel(name, schema),
        bindModel,
        setGroup
    };
}

module.exports = autoSwagger;
module.exports.RouteRegistry = RouteRegistry;
module.exports.createRouteInterceptor = createRouteInterceptor;
module.exports.createConfig = createConfig;
module.exports.generateOpenAPISpec = generateOpenAPISpec;
module.exports.transformRoutesToPaths = transformRoutesToPaths;
module.exports.createJsonEndpoint = createJsonEndpoint;
module.exports.createSwaggerUIEndpoint = createSwaggerUIEndpoint;
module.exports.normalizePath = normalizePath;
module.exports.loadModels = loadModels;
module.exports.extractGroupFromPath = extractGroupFromPath;